package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	for scanner.Scan() {
		line := scanner.Text()
		d, err := strconv.ParseInt(line, 10, 64)
		if err != nil {
			continue
		}
		fmt.Println(d/2 + 1)
	}
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" {
			continue
		}
		d, err := strconv.Atoi(line)
		if err != nil {
			continue
		}
		result := d/2 + 1
		fmt.Println(result)
	}
}

